      {
        "name": "tool_type",
        "type": "select",
        "required": true,
        "description": "Type of clinical trials search to perform",
        "options": [
          "search",
          "study_details",
          "results",
          "by_location",
          "by_sponsor",
          "advanced_search"
        ]
      },
      {
        "name": "condition",
        "type": "textarea",
        "required": false,
        "description": "Disease or condition being studied",
        "placeholder": "e.g., breast cancer, diabetes, COVID-19",
        "showWhen": {
          "parameter": "tool_type",
          "value": [
            "search",
            "advanced_search"
          ]
        }
      },
      {
        "name": "intervention",
        "type": "string",
        "required": false,
        "description": "Treatment or intervention being studied",
        "placeholder": "e.g., pembrolizumab, chemotherapy, diet",
        "showWhen": {
          "parameter": "tool_type",
          "value": [
            "search",
            "advanced_search"
          ]
        }
      },
      {
        "name": "phase",
        "type": "select",
        "required": false,
        "description": "Trial phase",
        "options": [
          "EARLY_PHASE1",
          "PHASE1",
          "PHASE2",
          "PHASE3",
          "PHASE4",
          "NA"
        ],
        "showWhen": {
          "parameter": "tool_type",
          "value": [
            "search",
            "advanced_search"
          ]
        }
      },
      {
        "name": "status",
        "type": "select",
        "required": false,
        "description": "Recruitment status",
        "options": [
          "NOT_YET_RECRUITING",
          "RECRUITING",
          "ENROLLING_BY_INVITATION",
          "ACTIVE_NOT_RECRUITING",
          "SUSPENDED",
          "TERMINATED",
          "COMPLETED",
          "WITHDRAWN"
        ],
        "showWhen": {
          "parameter": "tool_type",
          "value": [
            "search",
            "advanced_search"
          ]
        }
      },
      {
        "name": "country",
        "type": "string",
        "required": false,
        "description": "Country code (e.g., US, GB, CA)",
        "placeholder": "e.g., US, GB, CA, FR",
        "showWhen": {
          "parameter": "tool_type",
          "value": [
            "search",
            "by_location",
            "advanced_search"
          ]
        }
      },
      {
        "name": "state",
        "type": "string",
        "required": false,
        "description": "State/province (for US trials)",
        "placeholder": "e.g., California, New York, Texas",
        "showWhen": {
          "parameter": "tool_type",
          "value": [
            "by_location"
          ]
        }
      },
      {
        "name": "city",
        "type": "string",
        "required": false,
        "description": "City name",
        "placeholder": "e.g., Boston, London, Paris",
        "showWhen": {
          "parameter": "tool_type",
          "value": [
            "by_location"
          ]
        }
      },
      {
        "name": "nct_id",
        "type": "string",
        "required": true,
        "description": "NCT identifier (e.g., NCT04567890)",
        "placeholder": "e.g., NCT04567890",
        "showWhen": {
          "parameter": "tool_type",
          "value": [
            "study_details",
            "results"
          ]
        }
      },
      {
        "name": "sponsor",
        "type": "string",
        "required": true,
        "description": "Sponsor or organization name",
        "placeholder": "e.g., Merck, Mayo Clinic, NIH",
        "showWhen": {
          "parameter": "tool_type",
          "value": [
            "by_sponsor"
          ]
        }
      },
      {
        "name": "limit",
        "type": "number",
        "required": false,
        "description": "Maximum number of results (default: 20, max: 100)",
        "defaultValue": 20,
        "min": 1,
        "max": 100
      },
      {
        "name": "page",
        "type": "number",
        "required": false,
        "description": "Page number for pagination (starts at 1)",
        "defaultValue": 1,
        "min": 1,
        "max": 100
      }
    ],
    "executionMode": "instant",
    "version": "1.0.0",
    "author": "Bioinformatics Agent Team",
    "tags": [
      "clinical-medicine",
      "drug-discovery",
      "disease-research",
      "therapeutic-development"
    ]
  },
  "timestamp": "2026-11-03T15:13:11.899Z"
}

